///|
suberror AdapterError {
  AdapterError(String)
} derive(@debug.Debug)

///|
fn required(value : Json, name : String) -> String raise {
  match field(value, name) {
    Some(Json::String(text)) if text != "" => text
    _ => raise AdapterError("Missing or invalid \{name}")
  }
}

///|
fn environment(name : String) -> String raise {
  match @env.get_env_var(name) {
    Some(value) if value != "" => value
    _ => raise AdapterError("Missing \{name}")
  }
}

///|
fn quote(text : String) -> String {
  let escaped_quote =
    #|'"'"'
  "'" + text.replace_all(old="'", new=escaped_quote) + "'"
}

///|
async fn command_result(
  program : String,
  args : Array[String],
  stage : String,
  environment? : Map[String, String],
) -> (Int32, String) {
  save_diagnostic(stage, "started")
  let started = @env.now()
  let (status, output, errors) = {
    errdefer save_diagnostic(stage, "process-error", error_type="process_api")
    @process.collect_output(
      program,
      args,
      extra_env?=environment,
      inherit_env=environment is None,
    )
  }
  save_diagnostic(
    stage,
    if status == 0 {
      "success"
    } else {
      "exit-error"
    },
    exit_code=status,
    duration_ms=(@env.now() - started).to_double(),
    error_type?=if status == 0 {
      None
    } else {
      Some(process_error_type(errors.text()))
    },
  )
  (status, output.text())
}

///|
async fn command(
  program : String,
  args : Array[String],
  stage : String,
  environment? : Map[String, String],
) -> String {
  let (status, output) = command_result(program, args, stage, environment?)
  guard status == 0 else {
    raise AdapterError(
      "\{stage} failed (exit \{status}); command output withheld",
    )
  }
  output
}

///|
fn devsy_args(state : Json) -> Array[String] {
  let args = []
  for name in ["home", "context"] {
    if field(state, name) is Some(Json::String(value)) {
      args.push("--" + name)
      args.push(value)
    }
  }
  args
}

///|
async fn devsy_result(
  state : Json,
  args : Array[String],
  stage : String,
) -> (Int32, String) {
  let environment = @env.get_env_vars()
  for name in location_variables {
    match field(field(state, "devsyEnv").unwrap(), name) {
      Some(Json::String(value)) => environment.set(name, value)
      _ => environment.remove(name)
    }
  }
  let invocation = saved_command(state)
  let result = command_result(
    invocation[0],
    invocation[1:].to_owned() + devsy_args(state) + args,
    stage,
    environment~,
  )
  record_devsy_phases(result.1, stage)
  result
}

///|
async fn devsy(state : Json, args : Array[String], stage : String) -> String {
  let (status, output) = devsy_result(state, args, stage)
  guard status == 0 else {
    raise AdapterError(
      "\{stage} failed (exit \{status}); command output withheld",
    )
  }
  output
}

///|
fn saved_command(state : Json) -> Array[String] raise ConfigError {
  command_field(state, "recipeResult.userData").unwrap_or(["devsy"])
}

///|
fn set_field(value : Json, key : String, item : Json) -> Unit {
  if value is Json::Object(map) {
    map.set(key, item)
  }
}

///|
pub extend AdapterError with @debug.Debug::{to_repr}

///|
pub async fn execute(mode : String) -> Unit {
  execute_inner(mode) catch {
    InvalidConfig(message) => {
      @stdio.stderr.write("orca-env-devsy: " + message + "\n")
      save_diagnostic(mode, "failed")
      raise InvalidConfig(message)
    }
    AdapterError(message) => {
      @stdio.stderr.write("orca-env-devsy: " + message + "\n")
      save_diagnostic(mode, "failed")
      raise AdapterError(message)
    }
    _ => {
      save_diagnostic(mode, "failed")
      raise AdapterError("Operation failed; private command output withheld")
    }
  }
}

///|
fn validate_state(state : Json) -> Unit raise {
  ignore(saved_command(state))
  guard valid_workspace_id(required(state, "workspaceId")) &&
    valid_user(required(state, "user")) else {
    raise AdapterError("Invalid workspace identity")
  }
}

///|
async fn workspace(state : Json) -> Json? {
  let listing = @json.parse(
    devsy(
      state,
      ["--result-format", "json", "workspace", "list", "--skip-pro"],
      "workspace-list",
    ),
  )
  guard listing is Json::Array(items) else {
    raise AdapterError("Invalid workspace list")
  }
  let matches = items.filter(item => {
    field(item, "id") == field(state, "workspaceId")
  })
  match matches {
    [] => None
    [single] => Some(single)
    _ => raise AdapterError("Duplicate workspace ID")
  }
}

///|
fn valid_commit(value : String) -> Bool {
  (value.length() == 40 || value.length() == 64) &&
  value
  .to_array()
  .iter()
  .all(c => (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))
}

///|
pub async fn usage_error() -> Unit {
  @stdio.stderr.write(
    "Usage: orca-env-devsy <create|resume|suspend|destroy|reconnect>\n",
  )
  raise AdapterError("Invalid command")
}

///|
let location_variables : Array[String] = [
  "HOME", "DEVSY_HOME", "XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_CACHE_HOME", "XDG_STATE_HOME",
  "XDG_RUNTIME_DIR",
]

///|
async fn discard_created_workspace(state : Json) -> Unit {
  @async.protect_from_cancel(async fn() {
    try {
      @async.with_timeout(45000, async fn() {
        guard workspace(state) is Some(current) &&
          field(current, "uid") == field(state, "workspaceUid") else {
          return
        }
        if field(state, "user") is Some(_) {
          @async.with_timeout(15000, async fn() { close_tunnel(state) }) catch {
            _ => {
              save_diagnostic(
                "create-cleanup-tunnel",
                "warning",
                error_type="tunnel_cleanup",
              )
              @stdio.stderr.write(
                "orca-env-devsy: warning: tunnel cleanup failed; continuing workspace deletion\n",
              )
            }
          }
        }
        ignore(
          devsy(
            state,
            [
              "workspace",
              "delete",
              required(state, "workspaceId"),
              "--ignore-not-found",
            ],
            "create-cleanup",
          ),
        )
      })
      save_diagnostic("create-cleanup", "success")
    } catch {
      _ => {
        @stdio.stderr.write(
          "orca-env-devsy: warning: create cleanup failed; inspect the workspace with Devsy\n",
        )
        save_diagnostic("create-cleanup", "warning")
      }
    }
  })
}

///|
fn valid_workspace_id(id : String) -> Bool {
  id.length() > 0 &&
  id.length() <= 48 &&
  ((id[0] >= 'a' && id[0] <= 'z') || (id[0] >= '0' && id[0] <= '9')) &&
  id
  .to_array()
  .iter()
  .all(c => (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-')
}

///|
fn valid_context(value : String) -> Bool {
  value != "" &&
  value
  .to_array()
  .iter()
  .all(c => {
    (c >= 'a' && c <= 'z') ||
    (c >= 'A' && c <= 'Z') ||
    (c >= '0' && c <= '9') ||
    c == '_' ||
    c == '-'
  })
}

///|
fn valid_user(user : String) -> Bool {
  let name = if user.has_suffix("$") {
    user[:user.length() - 1].to_owned()
  } else {
    user
  }
  name != "" &&
  user.length() <= 64 &&
  (
    (name[0] >= 'a' && name[0] <= 'z') ||
    (name[0] >= 'A' && name[0] <= 'Z') ||
    name[0] == '_'
  ) &&
  name
  .to_array()
///|
async fn worker_alive(directory : String) -> Bool {
  let lock = @fs.open(
    directory + "/worker.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  !lock.try_lock(Exclusive)
}

///|
async fn tunnel_status(directory : String, status : String) -> Unit {
  let value : Json = { "status": status, "runId": recording_run_id }
  @fs.write_file(directory + "/status.tmp", value.stringify(), permission=0o600)
  @fs.rename(
    directory + "/status.tmp",
    directory + "/status.json",
    replace=true,
  )
  save_diagnostic("orca-tunnel", status)
}

///|
async fn adapter_executable() -> String {
  let name = @env.args()[0]
  if name.contains("/") {
    return @fs.realpath(name)
  }
  for directory in @env.get_env_var("PATH").unwrap_or("").split(":") {
    let path = directory.to_owned() + "/" + name
    if @fs.exists(path) {
      return @fs.realpath(path)
    }
  }
  raise AdapterError("Adapter executable is unavailable for tunnel recovery")
}

///|
async fn ensure_tunnel(state : Json, port : Int32) -> Unit {
  if field(state, "tunnelDirectory") is Some(Json::String(directory)) {
    if @fs.exists(directory + "/state.json") && worker_alive(directory) {
      let saved = @json.parse(@fs.read_file(directory + "/state.json").text())
      guard field(saved, "workspaceUid") == field(state, "workspaceUid") &&
        field(saved, "localPort") == Some(Json::number(port.to_double())) else {
        raise AdapterError("Tunnel ownership changed")
      }
      wait_tunnel(directory)
      return
    }
    close_tunnel(state)
  }
  let directory = @fs.tmpdir(prefix="oe")
  set_field(state, "tunnelDirectory", Json::string(directory))
  let saved = Json::empty_object()
  for
    name in [
      "workspaceId", "workspaceUid", "user", "command", "devsyEnv", "home", "context",
    ] {
    if field(state, name) is Some(value) {
      set_field(saved, name, value)
    }
  }
  set_field(saved, "localPort", Json::number(port.to_double()))
  @fs.write_file(directory + "/state.json", saved.stringify(), permission=0o600)
  errdefer close_tunnel(state)
  @fs.write_file(directory + "/enabled", "", permission=0o600)
  let sink = @process.redirect_to_file("/dev/null", shared=true)
  defer sink.close()
  ignore(
    @process.spawn_orphan(
      adapter_executable(),
      ["--tunnel-worker", directory],
      stdin=@process.redirect_from_file("/dev/null"),
      stdout=sink,
      stderr=sink,
    ),
  )
  wait_tunnel(directory)
}

///|
async fn wait_tunnel(directory : String) -> Unit {
  @async.with_timeout(30000, async fn() {
    while true {
      if @fs.exists(directory + "/status.json") && worker_alive(directory) {
        let status = @json.parse(
          @fs.read_file(directory + "/status.json").text(),
        )
        if field(status, "status") == Some(Json::string("connected")) {
          let saved = @json.parse(
            @fs.read_file(directory + "/state.json").text(),
          )
          try {
            check_tunnel(saved, directory)
            return
          } catch {
            _ => ()
          }
        }
      }
      @async.sleep(100)
    }
  })
}

///|
async fn close_tunnel(state : Json) -> Unit {
  guard field(state, "tunnelDirectory") is Some(Json::String(directory)) else {
    return
  }
  if !@fs.exists(directory) {
    return
  }
  if @fs.exists(directory + "/state.json") {
    let saved = @json.parse(@fs.read_file(directory + "/state.json").text())
    guard field(saved, "workspaceUid") == field(state, "workspaceUid") else {
      raise AdapterError("Tunnel ownership changed")
    }
    if @fs.exists(directory + "/enabled") {
      @fs.remove(directory + "/enabled")
    }
    @async.with_timeout(15000, async fn() {
      while worker_alive(directory) {
        @async.sleep(100)
      }
    })
    // Only remove this worker's files; retain unexpected directory contents.
    for
      name in [
        "state.json", "status.json", "status.tmp", "worker.lock", "socket",
      ] {
      if @fs.exists(directory + "/" + name) {
        @fs.remove(directory + "/" + name)
      }
    }
  } else {
    // Saved receipts from before the recovery worker own an SSH master only.
    ignore(
      @process.collect_output(
        "ssh",
        ssh_args(state) + ["-S", directory + "/socket", "-O", "exit"],
      ),
    )
  }
  @fs.rmdir(directory) catch {
    _ => ()
  }
}

///|
pub async fn tunnel_worker(directory : String) -> Unit {
  let lock = @fs.open(
    directory + "/worker.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  if !lock.try_lock(Exclusive) {
    return
  }
  let state = @json.parse(@fs.read_file(directory + "/state.json").text())
  validate_state(state)
  let port = match field(state, "localPort") {
    Some(Json::Number(value, ..)) => value.to_int()
    _ => raise AdapterError("Missing tunnel port")
  }
  let enabled = directory + "/enabled"
  let mut attempt = 0
  while @fs.exists(enabled) {
    tunnel_status(directory, "connecting")
    @async.with_task_group(async fn(group) {
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      // A saved ID alone must not reconnect into a replacement workspace.
      guard worker_workspace(state, directory) is Some(current) &&
        field(current, "uid") == field(state, "workspaceUid") else {
        if @fs.exists(enabled) {
          @fs.remove(enabled)
        }
        tunnel_status(directory, "ownership-error")
        return
      }
      // The worker owns this master and reaps it before reconnecting.
      let (errors, stderr) = @process.read_from_process()
      defer errors.close()
      let classified = group.spawn(
        async fn() { tunnel_errors(errors) },
        no_wait=true,
      )
      let child = @process.spawn(
        group,
        "ssh",
        ssh_args(state) +
        [
          "-M",
          "-S",
          directory + "/socket",
          "-N",
          "-o",
          "ExitOnForwardFailure=yes",
          "-o",
          "ServerAliveInterval=10",
          "-o",
          "ServerAliveCountMax=3",
          "-L",
          "127.0.0.1:\{port}:127.0.0.1:47121",
        ],
        stdin=@process.redirect_from_file("/dev/null"),
        stdout=sink,
        stderr~,
        no_wait=true,
      )
      let mut connected = false
      while @fs.exists(enabled) && child.try_wait() is None {
        if !connected {
          try {
            check_tunnel(state, directory)
            connected = true
            attempt = 0
            tunnel_status(directory, "connected")
          } catch {
            _ => ()
          }
        }
        @async.sleep(100)
      }
      if !@fs.exists(enabled) {
        @async.with_timeout(2000, async fn() {
          ignore(
            @process.collect_output(
              "ssh",
              ssh_args(state) + ["-S", directory + "/socket", "-O", "exit"],
            ),
          )
        }) catch {
          _ => ()
        }
        child.cancel()
      } else {
        let code = child.wait()
        save_diagnostic(
          "orca-tunnel",
          "disconnected",
          exit_code=code,
          error_type=@async.with_timeout(1000, async fn() { classified.wait() }) catch {
            _ => "process_exit"
          },
        )
      }
    }) catch {
      _ => save_diagnostic("orca-tunnel", "process-error")
    }
    if @fs.exists(enabled) {
      tunnel_status(directory, "disconnected")
      attempt = if attempt < 6 { attempt + 1 } else { 6 }
      let delay = if attempt < 6 { 500 * (1 << attempt) } else { 30000 }
      save_diagnostic("orca-tunnel", "retry", attempt~, retry_delay_ms=delay)
      for elapsed = 0
          elapsed < delay && @fs.exists(enabled)
          elapsed = elapsed + 100 {
        @async.sleep(100)
      }
    }
  }
  tunnel_status(directory, "stopped")
}

///|
async fn check_tunnel(state : Json, directory : String) -> Unit {
  @async.with_timeout(2000, async fn() {
    let (status, _, _) = @process.collect_output(
      "ssh",
      ssh_args(state) + ["-S", directory + "/socket", "-O", "check"],
    )
    guard status == 0 else { raise AdapterError("Tunnel not ready") }
    let port = match field(state, "localPort") {
      Some(Json::Number(value, ..)) => value.to_int()
      _ => raise AdapterError("Missing tunnel port")
    }
    let socket = @socket.Tcp::connect(
      @socket.Addr::parse("127.0.0.1:" + port.to_string()),
    )
    socket.close()
  })
}

///|
async fn worker_workspace(state : Json, directory : String) -> Json? {
  @async.with_timeout(10000, async fn() {
    @async.with_task_group(async fn(group) {
      let query = group.spawn(async fn() { workspace(state) })
      group.spawn_bg(no_wait=true, async fn() {
        while @fs.exists(directory + "/enabled") {
          @async.sleep(100)
        }
        query.cancel()
      })
      query.wait()
    })
  })
}

